    if (p.action === 'draftyes') { const usage = this.db.select().from(publications).where(eq(publications.templateId, tpl.id)).all().length; this.db.update(templates).set({ isDraft: true }).where(eq(templates.id, tpl.id)).run(); this.audit(i.guildId, i.user.id, tpl.organizationId, 'template.draft_changed', { templateId: tpl.id, isDraft: true, affectedPublications: usage }); this.refreshOrganization(tpl.organizationId); await i.update(templatePanel({ ...tpl, isDraft: true }, this.organizationById(i.guildId, tpl.organizationId).name, i.user.id, usage, `✅ 게시물 ${usage}개에 영향을 주는 것을 확인하고 초안으로 전환했습니다.`, browserPage)); return; }
