    if (p.action === 'deleteyes') { if (this.db.select().from(publications).where(eq(publications.templateId, tpl.id)).get()) throw new ApplicationError('VALIDATION_ERROR', '게시 설정에서 사용하는 템플릿은 삭제할 수 없습니다.'); this.db.delete(templates).where(eq(templates.id, tpl.id)).run(); this.audit(i.guildId, i.user.id, tpl.organizationId, 'template.deleted', { templateId: tpl.id }); this.refreshOrganization(tpl.organizationId); await i.update({ ...templateBrowser(this.templateItems(i.guildId, tpl.organizationId), i.user.id, tpl.organizationId, browserPage), content: '✅ 템플릿을 삭제했습니다.' }); return; }
    if (p.action === 'edit') { const input = new TextInputBuilder().setCustomId('content').setLabel('Liquid 템플릿 내용').setStyle(TextInputStyle.Paragraph).setValue(tpl.content.slice(0, 4000)).setMaxLength(4000).setRequired(true); await i.showModal(new ModalBuilder().setCustomId(customId('tpl', 'editmodal', p.target, i.user.id)).setTitle('템플릿 편집').addComponents(new ActionRowBuilder<TextInputBuilder>().addComponents(input))); return; }
