  private publicationCreateSession(guildId: string, userId: string, id: string) { const session = this.db.select().from(setupSessions).where(eq(setupSessions.id, id)).get(); if (!session || session.kind !== 'publication_create' || session.guildId !== guildId || session.userId !== userId || session.expiresAt <= new Date()) throw new ApplicationError('VALIDATION_ERROR', '게시물 만들기 화면이 만료되었습니다.'); return session; }
