    if (p.action === 'new') { const { id: orgId, page } = targetPage(p.target); this.organizationById(i.guildId, orgId); await i.update({ content: '게시할 텍스트·공지·포럼 채널을 선택하세요.', embeds: [], components: [new ActionRowBuilder<ChannelSelectMenuBuilder>().addComponents(new ChannelSelectMenuBuilder().setCustomId(managementId('pub', 'newchannel', pageTarget(orgId, page), i.user.id)).setPlaceholder('게시 채널 선택').setChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement, ChannelType.GuildForum))] }); return; }
