      if (p.action === 'createcancel') { this.db.delete(setupSessions).where(eq(setupSessions.id, session.id)).run(); await i.update({ ...publicationBrowser(this.publicationItems(i.guildId, org.id, i.guild.channels.cache.mapValues((channel) => channel.name)), i.user.id, org.id), content: '게시물 만들기를 취소했습니다.' }); return; }
