    if (p.action === 'templatechange') { const candidates = this.db.select().from(templates).where(and(eq(templates.organizationId, pub.organizationId), eq(templates.isDraft, false))).all().slice(0, 25); if (!candidates.length) throw new ApplicationError('NOT_FOUND', '변경할 수 있는 사용 가능 템플릿이 없습니다.'); await i.reply({ content: '게시물에 사용할 템플릿을 선택하세요. 초안은 제외됩니다.', components: [new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(new StringSelectMenuBuilder().setCustomId(customId('pub', 'changetpl', p.target, i.user.id)).setPlaceholder('사용 가능 템플릿 선택').addOptions(candidates.map((template) => new StringSelectMenuOptionBuilder().setLabel(template.name.slice(0, 100)).setValue(String(template.id)))))], ephemeral: true }); return; }
