  private async publicationModal(i: ModalSubmitInteraction<'cached'>, p: ParsedCustomId) {
    if (p.action === 'createsettingsmodal') { const session = this.publicationCreateSession(i.guildId, i.user.id, p.target); const forum = session.state.forum as Record<string, unknown> | null; if (!forum) throw new ApplicationError('VALIDATION_ERROR', '포럼 게시 설정이 아닙니다.'); const archive = Number(i.fields.getTextInputValue('archive')); const slowmode = Number(i.fields.getTextInputValue('slowmode')); if (![60, 1440, 4320, 10080].includes(archive) || !Number.isInteger(slowmode) || slowmode < 0 || slowmode > 21600) throw new ApplicationError('VALIDATION_ERROR', '자동 보관 시간 또는 slowmode 값이 Discord 범위를 벗어났습니다.'); const flags = new Set(i.fields.getTextInputValue('flags').split(',').map((value) => value.trim().toLowerCase()).filter(Boolean)); const nextForum = { ...forum, titleTemplate: i.fields.getTextInputValue('title'), autoArchiveDuration: archive, slowmodeSeconds: slowmode, archiveAfterPublish: flags.has('archive'), lockAfterPublish: flags.has('lock'), preserveManualTags: flags.has('preserve_manual_tags') }; const fresh = { ...session, state: { ...session.state, forum: nextForum } }; this.db.update(setupSessions).set({ state: fresh.state }).where(eq(setupSessions.id, session.id)).run(); const conflict = Boolean(session.state.autoRefresh) && flags.has('lock'); await i.reply({ ...this.publicationCreationPanel(fresh, i, conflict ? '⚠️ 게시 후 잠금과 자동 갱신이 충돌합니다. 잠금을 끄거나 자동 갱신을 끄세요.' : '✅ 게시 전 포럼 설정을 저장했습니다.'), ephemeral: true }); return; }
    const { id: publicationId } = targetPage(p.target); const pub = this.publication(i.guildId, publicationId);
    if (p.action === 'editmodal') { const auto = i.fields.getTextInputValue('auto').trim().toLowerCase(); if (!['true', 'false'].includes(auto)) throw new ApplicationError('VALIDATION_ERROR', '자동 갱신 값은 true 또는 false여야 합니다.'); const forum = this.db.select().from(forumPublicationSettings).where(eq(forumPublicationSettings.publicationId, pub.id)).get(); if (auto === 'true' && forum?.lockAfterPublish) throw new ApplicationError('VALIDATION_ERROR', '게시 후 잠금이 켜진 포럼에는 자동 갱신을 켤 수 없습니다.'); this.db.update(publications).set({ name: i.fields.getTextInputValue('name').trim(), autoRefresh: auto === 'true' }).where(eq(publications.id, pub.id)).run(); this.audit(i.guildId, i.user.id, pub.organizationId, 'publication.updated', { publicationId: pub.id }); const fresh = this.publication(i.guildId, pub.id); await i.reply({ ...this.publicationDetail(fresh, i, '✅ 게시 설정을 수정했습니다.'), ephemeral: true }); return; }
    if (p.action === 'forumsettingsmodal') { const forum = this.db.select().from(forumPublicationSettings).where(eq(forumPublicationSettings.publicationId, pub.id)).get(); if (!forum) throw new ApplicationError('VALIDATION_ERROR', '포럼 게시 설정이 아닙니다.'); const archive = Number(i.fields.getTextInputValue('archive')); const slowmode = Number(i.fields.getTextInputValue('slowmode')); if (![60, 1440, 4320, 10080].includes(archive) || !Number.isInteger(slowmode) || slowmode < 0 || slowmode > 21600) throw new ApplicationError('VALIDATION_ERROR', '자동 보관 시간 또는 slowmode 값이 Discord 범위를 벗어났습니다.'); const flags = new Set(i.fields.getTextInputValue('flags').split(',').map((value) => value.trim().toLowerCase()).filter(Boolean)); if (flags.has('lock') && pub.autoRefresh) throw new ApplicationError('VALIDATION_ERROR', '게시 후 잠금과 자동 갱신을 함께 사용할 수 없습니다. 먼저 자동 갱신을 끄세요.'); this.db.update(forumPublicationSettings).set({ titleTemplate: i.fields.getTextInputValue('title'), autoArchiveDuration: archive, slowmodeSeconds: slowmode, archiveAfterPublish: flags.has('archive'), lockAfterPublish: flags.has('lock'), preserveManualTags: flags.has('preserve_manual_tags') }).where(eq(forumPublicationSettings.publicationId, pub.id)).run(); this.audit(i.guildId, i.user.id, pub.organizationId, 'publication.forum_settings_updated', { publicationId: pub.id }); this.refreshOrganization(pub.organizationId); await i.reply({ ...this.publicationDetail(pub, i, '✅ 포럼 제목과 스레드 설정을 저장했습니다.'), ephemeral: true }); return; }
    if (p.action === 'reconnectmodal') { const messageId = i.fields.getTextInputValue('message').trim(); if (!/^\d{15,22}$/.test(messageId)) throw new ApplicationError('VALIDATION_ERROR', '유효한 Discord 메시지 ID를 입력하세요.'); const channel = await i.guild.channels.fetch(pub.channelId); if (!channel) throw new ApplicationError('NOT_FOUND', '게시 대상 채널을 찾을 수 없습니다.'); const forum = this.db.select().from(forumPublicationSettings).where(eq(forumPublicationSettings.publicationId, pub.id)).get(); if (forum) { const threadId = i.fields.getTextInputValue('thread').trim(); const thread = await i.guild.channels.fetch(threadId); if (!thread?.isThread() || thread.parentId !== pub.channelId) throw new ApplicationError('VALIDATION_ERROR', '이 포럼에 속한 thread ID를 입력하세요.'); await thread.messages.fetch(messageId); this.db.update(forumPublicationSettings).set({ threadId }).where(eq(forumPublicationSettings.publicationId, pub.id)).run(); } else { if (!channel.isTextBased()) throw new ApplicationError('VALIDATION_ERROR', '메시지를 찾을 수 있는 채널이 아닙니다.'); await channel.messages.fetch(messageId); } this.db.update(publications).set({ messageId, broken: false, lastRenderError: null }).where(eq(publications.id, pub.id)).run(); this.audit(i.guildId, i.user.id, pub.organizationId, 'publication.reconnected', { publicationId: pub.id, messageId }); await i.reply({ ...this.publicationDetail(this.publication(i.guildId, pub.id), i, '✅ 기존 Discord 게시물에 다시 연결했습니다.'), ephemeral: true }); return; }
    throw new ApplicationError('VALIDATION_ERROR', '지원하지 않는 게시 설정 입력입니다.');
  }
  private diagnosticsText(rows: ReadonlyArray<{ code: string; message: string }>) { return rows.length ? `\n\n**진단**\n${rows.map((r) => `⚠️ [${r.code}] ${r.message}`).join('\n')}` : '\n진단: 정상'; }
